        # Build adjacency list
        adj = [[] for _ in range(n + 1)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        # BFS initialization
        distance = [-1] * (n + 1)
        distance[s] = 0
        q_bfs = deque([s])
        # Perform BFS
        while q_bfs:
            u = q_bfs.popleft()
            for v in adj[u]:
                if distance[v] == -1:
                    distance[v] = distance[u] + 1
                    q_bfs.append(v)
        # Generate result
        result = []
        for i in range(1, n + 1):
            if i == s:
                continue
            if distance[i] == -1:
                result.append(-1)
            else:
                result.append(distance[i] * 6)
        # Print result
